<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;use App\Models\ReferralAgent;use App\Services\ReferralCommissions;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Support\Str;
class CandidateReferralController extends Controller{public function __construct(private readonly ReferralCommissions $commissions){}public function show(Request $r):JsonResponse{$a=ReferralAgent::firstOrCreate(['user_id'=>$r->user()->id],['qr_code_token'=>Str::random(24)]);$registrations=$a->registrations()->with('candidateProfile:id,first_name,last_name,submitted_at')->latest('registered_at')->get()->map(fn($x)=>['id'=>$x->id,'candidate_name'=>trim(($x->candidateProfile?->first_name??'').' '.($x->candidateProfile?->last_name??''))?:null,'status'=>$x->commission_status,'registered_at'=>$x->registered_at]);return response()->json(['code'=>$a->qr_code_token,'registrations_count'=>$registrations->count(),'registrations'=>$registrations,'earnings'=>$this->commissions->summaryFor($a->id)]);}}
